insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('1', 'The Driver', 'communication_style', 'Direct, fast, and decisive. Speaks in short sentences and makes quick calls. Values speed and results above everything else. Under stress becomes blunt, dismissive, and aggressive — the team hears criticism when the founder only intended urgency.', '["Uses short declarative sentences with no preamble or context", "Focuses entirely on outcomes and speed — not process or people", "Makes decisions in the room without consulting the team first", "Interrupts explanations to ask for the bottom line", "Under stress: snaps instructions that feel aggressive even without intent to harm", "Takes back delegated tasks when pace feels too slow"]', '["Just do it", "We are switching direction", "Next", "What is the bottom line", "I will handle this myself", "We just need to push harder", "Cut to the point", "What is the fastest way"]', 'Just tell me what to do and I will execute', 'I am moving fast because slowing down feels dangerous right now', 'Match their pace. Lead with the action or recommendation first. Give the one most important piece of context after — not before. Do not ask how they feel before giving them something useful.', '["RC-661", "RC-664", "RC-693"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.685858+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('2', 'The Visionary', 'communication_style', 'Communicates in big ideas, possibilities, and stories. Inspiring and can paint a compelling picture of the future. Under stress dismisses details, makes promises they cannot keep, and uses big vision language to avoid addressing real problems.', '["Speaks in metaphors, possibilities, and future states rather than current reality", "Energises rooms but struggles to connect vision to concrete next steps", "Under stress: makes commitments without checking feasibility", "Uses vision language to redirect uncomfortable conversations", "Team often inspired but confused about what to actually do next", "Details feel like obstacles rather than tools"]', '["Imagine if we", "We are going to be a category leader", "Do not worry about the details", "We will figure it out", "The potential here is unlimited", "Trust the vision", "This is going to change everything"]', 'Do not worry about the details — the vision is what matters', 'I am avoiding the details because I do not have answers to them yet and that terrifies me', 'Acknowledge the vision first — it is real and important. Then gently anchor it: ask what the next 30-day milestone looks like in concrete terms. Do not challenge the vision — help them build a bridge from vision to execution.', '["RC-668", "RC-676", "RC-679"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.74314+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('3', 'The Analyst', 'communication_style', 'Thinks before speaking. Asks many questions, wants to understand deeply before committing. Under stress over-analyses, stalls decisions, and asks for more information as a way to avoid committing. The team sees indecision; the founder sees responsibility.', '["Long pauses before answering — visibly processing before responding", "Asks clarifying questions before committing to any position", "Seeks data and evidence before making decisions", "Under stress: requests more information as a delay tactic rather than genuine need", "Can identify risks in any plan — which stalls action when stress is high", "Meetings often end without a decision because more data is needed"]', '["Let me think about that", "Can we look at the data again", "I am not sure we have enough information yet", "What does the research say", "I want to make sure we have considered everything", "Let me get back to you on that", "There are a few more things I need to understand first"]', 'I need more data before I can commit to this direction', 'I am afraid of making the wrong call and the uncertainty is overwhelming me', 'Validate the need for clarity — it is real. Then name the trap: the data they need may not exist yet, and a decision made on incomplete information is still better than no decision. Help them define what minimum information is actually sufficient to act.', '["RC-670", "RC-687", "RC-690"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.894064+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('4', 'The Harmoniser', 'communication_style', 'Values relationships, team wellbeing, and harmony. Uses inclusive language. Avoids conflict. Under stress avoids difficult conversations, agrees externally while disagreeing internally, and smooths over real problems until they become crises.', '["Uses we language even for personal decisions", "Checks in on how everyone feels before pushing a direction", "Visibly uncomfortable when there is tension in the room", "Under stress: agrees in meetings, then reverses or stalls outside of them", "Avoids performance conversations, equity conflicts, co-founder misalignment", "Problems that should be addressed early get left until they are serious"]', '["How does everyone feel about this", "I am sure we will work it out", "Let us not make it a big deal", "I do not want to upset anyone", "We are all aligned — right", "I think everyone is mostly happy", "I do not want to create conflict"]', 'I think we are mostly aligned — let us keep moving', 'There is a problem I cannot bring myself to name because the conflict feels too dangerous', 'Create safety before surfacing the difficult thing. Acknowledge that wanting harmony is healthy. Then name the cost of avoiding: the problem does not disappear — it grows. Ask what they would tell a friend in this situation.', '["RC-671", "RC-673", "RC-694"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.569221+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('5', 'Hyperactivity Mode', 'stress_response', 'Under extreme stress the founder speeds up. Works longer hours, sends more messages, makes rapid decisions, and fills every moment with activity. This looks like hustle from outside but is anxiety driving the behaviour — staying busy feels safer than facing what is going wrong.', '["Late night messages sent to team at unusual hours", "Frantic context switching between unrelated tasks", "Making decisions without consulting the team or waiting for input", "Taking back tasks that were previously delegated", "Activity level high but output quality declining", "Multiple initiatives launched simultaneously with no clear priority"]', '["We just need to push harder", "I will handle this myself", "Let us just do all of it", "We cannot slow down now", "I do not have time to explain — just do it", "Every hour counts right now", "I am on top of everything"]', 'We just need to push harder — let us go', 'I am scared and I do not know what else to do so I am filling the space with action', 'Do not mirror the urgency — it amplifies the anxiety. Slow the pace deliberately. Acknowledge the pressure first. Then ask: of everything on your plate right now, what is the one thing that actually moves the needle? Help them find the signal inside the noise.', '["RC-665", "RC-698", "RC-701"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.946753+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('6', 'Withdrawal Mode', 'stress_response', 'Under extreme stress the founder slows down or disappears. Stops responding to messages, avoids conversations, cancels meetings, and becomes very quiet. Looks like avoidance from outside but is almost always driven by shame, overwhelm, or burnout.', '["Response times to messages increasing significantly", "Calls cancelled or rescheduled at the last minute repeatedly", "Missing investor or team updates without explanation", "Flat or monotone communication — energy has disappeared", "Going quiet after a setback or difficult piece of news", "Avoiding people who might ask how things are going"]', '["It is fine — we will figure it out", "I am just busy right now", "Nothing major", "Do not worry about me", "I am dealing with some things", "I will get back to you soon", "Everything is under control"]', 'I am just busy — I will get back to you', 'I do not know how to face this and I am exhausted and ashamed', 'Do not confront the withdrawal directly — it creates more shame. Instead open a door: acknowledge that things seem quieter than usual and that this is a safe space to say what is actually going on. Normalise the struggle before asking anything about the business.', '["RC-666", "RC-699", "RC-702"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.147764+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('7', 'Burnout Stage 1 — Emotional Exhaustion', 'burnout_stage', 'The founder is tired all the time. More irritable than usual. Small things frustrate them disproportionately. They still show up but their energy is clearly depleted. Language becomes more negative and complaints increase. This is the earliest and most recoverable stage.', '["Visible tiredness that does not improve after rest", "Irritability about small things that would not have bothered them before", "More complaints and negative framing of the same situations", "Still executing but with noticeably less enthusiasm", "Physical fatigue present even in morning hours", "Shorter patience with team questions or delays"]', '["I am just so tired lately", "Everything feels like an effort right now", "I did not sleep well again", "I am just frustrated with everything at the moment", "I cannot seem to switch off", "Even small things feel heavy right now", "I keep running on empty"]', 'I am just tired — it is a busy period', 'I have been running on empty for longer than I have admitted and I do not know when it will stop', 'Acknowledge the exhaustion without minimising it or immediately moving to solutions. Ask when they last had a full day off. Name what you are observing without judgment. This is the stage where early intervention has the most impact.', '["RC-703", "RC-707", "RC-711"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.996623+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('8', 'Burnout Stage 2 — Cynicism and Detachment', 'burnout_stage', 'The founder emotionally distances themselves from the work. Becomes dismissive of ideas, critical of team members, and less responsive to feedback. Language becomes sarcastic. They are still present physically but emotionally they have already partially checked out.', '["Dismissive responses to ideas that would previously have generated enthusiasm", "Critical or sarcastic comments about the team or the business", "Less responsiveness to positive news — it does not seem to register", "Distance from the team — fewer check-ins, less personal connection", "Questions from team feel like interruptions rather than engagement", "Long periods of silence in what used to be active conversations"]', '["I do not even care anymore", "What is the point", "Whatever — just do what you think", "It does not matter", "That is just how it is", "I have heard that before", "Sure — whatever"]', 'I do not really care how we do it — just get it done', 'I am emotionally exhausted and have started detaching as a self-protection mechanism', 'This stage requires more care than the first. Do not push on business questions yet. Ask when they last felt genuinely excited about something — in the business or outside it. The question you are answering is: is the passion still there beneath the detachment, or has it gone completely?', '["RC-704", "RC-708", "RC-712"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.200905+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('9', 'Burnout Stage 3 — Complete Ineffectiveness', 'burnout_stage', 'The founder can no longer function effectively. Decision-making stops. Execution collapses. Communication breaks down entirely. This stage almost always requires significant personal support beyond business coaching. Reaching this stage means earlier signals were missed or ignored.', '["Key decisions not being made — business effectively paralysed", "Communication has stopped — messages unanswered, meetings missed", "Team members acting without direction because there is none", "Physical symptoms prominent — unable to sleep, not eating, health declining", "Statements of hopelessness or catastrophic certainty about the future", "Founder may be considering walking away from the business entirely"]', '["I cannot do this anymore", "I do not know who I am without this", "Everything is falling apart", "It is over", "I have nothing left", "I have failed everyone", "I should never have started this"]', 'I just cannot do this anymore', 'I have hit the wall that I have been heading toward for a long time and I need real support — not business advice', 'This is not a business conversation. Acknowledge the pain directly and without minimising it. Do not offer frameworks or strategies. Ask if they have someone — a person, not an AI — they can speak to today. If distress signals are present this triggers the Distress Protocol immediately.', '["RC-705", "RC-709", "RC-713"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.050269+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('10', 'Excessive Reassurance Language', 'language_signal', 'Saying ''it is fine'', ''we will figure it out'', ''not a problem'' repeatedly — especially about serious issues — almost always signals hidden concern. The more emphatically a founder says everything is fine, the more worth exploring what is actually going on beneath that.', '["Phrases like ''it is fine'' or ''we will figure it out'' used to close down topics rather than engage with them", "Reassurance offered before any question is even asked", "Minimising language used consistently about issues that are objectively serious", "Upbeat framing immediately after delivering bad news", "Quickly moving on from difficult topics without fully addressing them"]', '["It is fine — we will figure it out", "Not a problem at all", "We are totally on top of it", "I am not worried", "It is not as bad as it sounds", "We have dealt with worse", "Everything is under control"]', 'It is fine — not a problem', 'I am worried about this but I am not ready to admit it — to you or to myself', 'Do not challenge the reassurance directly. Instead open a door: ''It sounds like you are managing it well — what has the last week actually felt like while you were dealing with it?'' The goal is to make honesty feel safe, not to catch them in a contradiction.', '["RC-667", "RC-696", "RC-714"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.25337+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('11', 'Absolutist Language', 'language_signal', 'Words like always, never, completely, impossible, definitely used when discussing uncertain situations signal black and white thinking under pressure. Absolutist language is a cognitive distortion that narrows the founder''s perception of their options.', '["Binary framing of complex situations — it is either working or it is completely failing", "No nuance or middle ground in descriptions of performance or team", "Catastrophic certainty about future outcomes that are actually uncertain", "Dismissing partial progress because it is not complete success", "Using ''never'' and ''always'' to describe patterns that are actually variable"]', '["We will never recover from this", "This always happens to us", "It is completely impossible", "Nobody ever listens", "Everything is falling apart", "It is definitely over", "We have always been bad at this"]', 'We will never be able to fix this', 'I am in a high-stress state right now and my thinking has narrowed to worst-case scenarios', 'Acknowledge the feeling without reinforcing the absolute framing. Gently introduce specificity: ''When you say never — has there been any moment in the last month where it felt even slightly different?'' The goal is to widen the aperture without dismissing the fear.', '["RC-668", "RC-697", "RC-715"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.100011+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('12', 'Avoidance Hedging', 'language_signal', 'Phrases like maybe, perhaps, we might consider, I am not saying no but — indicate reluctance and discomfort the founder cannot directly express. Hedging is how founders soften a reality they are not yet ready to fully state.', '["Commitments always qualified with conditions that delay action", "Answers to direct questions answered with questions or possibilities rather than positions", "Reluctance to say yes or no — always a qualified maybe", "Plans described as things that might happen rather than things that will happen", "Using others as reason for delay: waiting on the team, the market, the data"]', '["Maybe we could consider", "Perhaps at some point", "I am not saying no but", "We might look into that", "It is possible we could", "I am not sure we are ready for that yet", "Let me think about whether that makes sense"]', 'Maybe we could look at that at some point', 'I am not comfortable with this but I cannot say that directly — I do not know how to have this conversation', 'Name the hedge gently without making it feel like an accusation: ''It sounds like there might be some hesitation here — what is the concern?'' Give them permission to say the uncomfortable thing by making it safe to say it.', '["RC-669", "RC-695", "RC-716"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.792414+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('13', 'Passive Voice and Accountability Deflection', 'language_signal', 'Mistakes were made rather than I made a mistake. Shifting from I to we during failure discussions. This signals the founder cannot yet take full ownership — often a sign of shame, overwhelm, or the fear that admitting responsibility makes them look weak.', '["Describing failures using passive voice — things happened rather than I did or I decided", "Shifting from I to we specifically when describing what went wrong", "Framing mistakes as team or market failures rather than leadership decisions", "Unable to say the words ''I got this wrong'' directly", "Over-explaining context around failures in a way that distributes blame"]', '["Mistakes were made", "Things did not go as planned", "The team struggled with", "It turned out that", "Circumstances changed", "We faced some challenges", "It was not clear at the time"]', 'Mistakes were made and we are learning from them', 'I know I got this wrong and I am ashamed to say it directly because I am afraid of what it means about me', 'Do not push for the I statement — that creates shame. Instead normalise ownership: ''Every founder I have spoken to has made calls they would redo. What would you do differently with what you know now?'' This lets them engage with the learning without the shame of the admission.', '["RC-672", "RC-700", "RC-717"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.357866+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('14', 'Over-Use of Positive Superlatives', 'language_signal', 'Words like incredible, revolutionary, amazing, definitely used frequently in uncertain contexts often mask anxiety about those same outcomes. When a founder works very hard to convince you things are great, they are often simultaneously trying to convince themselves.', '["Superlative language used consistently even for ordinary progress", "Energy spent emphasising how well things are going before any concern is raised", "Investor or team updates that feel more like performance than report", "No acknowledgment of difficulty or uncertainty alongside the positives", "Pushback on any balanced or neutral framing — everything must be incredible or failed"]', '["This is incredible traction", "The response has been amazing", "We are absolutely killing it", "Investors love us", "Everything is going perfectly", "The market feedback has been revolutionary", "We have never been in a better position"]', 'Everything is going amazingly — we are in a really strong position', 'I am performing confidence because I am scared that if I show doubt it will become real or someone will lose faith in me', 'Do not challenge the positivity directly — it creates defensiveness. Instead gently introduce balance: ''It sounds like there is a lot of positive momentum. What is the one thing that keeps you up at night despite all of that?'' This gives them permission to name the fear without having to abandon the confident framing.', '["RC-674", "RC-686", "RC-718"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.305466+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('15', 'Fragmented or Rushed Speech', 'language_signal', 'Short incomplete sentences, filler words, trailing off mid-thought. These are signs of high cognitive load and stress. When a founder is overwhelmed they can no longer hold the full thought in working memory long enough to complete it.', '["Sentences starting but not finishing — trailing off before the key point", "High use of filler words that fill space while the brain catches up", "Jumping between topics before completing the previous one", "Visible searching for words they would normally have ready", "Answers to questions that circle around the point without landing", "Speaking noticeably faster than their normal pace"]', '["So basically what I mean is — anyway", "It is like — you know what I mean", "There is so much happening that — yeah", "I have been meaning to — it is hard to explain", "We are working on — there are a few things", "I cannot even — there is just so much"]', 'There is just — it is hard to even explain right now', 'I am so cognitively and emotionally overloaded right now that I cannot form coherent thoughts — I need space and simplicity', 'Slow everything down. Reduce the cognitive load. Ask one simple question at a time and give long pauses after. Do not rush to fill silence — the most important things often come after a pause. The founder does not need more input right now — they need space to hear themselves think.', '["RC-675", "RC-688", "RC-719"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.408498+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('16', 'Mind Layer — Cognitive Pattern', 'language_signal', 'How the founder processes information. Covers decision-making logic, thinking style (intuitive vs analytical), and cognitive biases. 81% of founders believe they have a 70%+ chance of success despite real failure rates. Biases like overconfidence, sunk cost, and status-quo profoundly shape decisions.', '["Fast but risky: decides quickly and adjusts later without adequate planning", "Delayed: cannot act until all data is available — which never happens", "Strong belief maintained despite contrary evidence from market or team", "Over-simplifying complexity — reducing nuanced problems to binary choices", "Inconsistent reasoning quality across different topics — sharp in some areas, blind in others"]', '["I decide quickly and adjust later", "I cannot act until I have all the data", "I just know this is right", "We tried that — it does not work", "The data will catch up to the vision", "My gut has never been wrong on this"]', 'I just know this is the right direction — I can feel it', 'I am making an intuitive call and hoping the logic validates itself — I may not have checked whether the evidence actually supports this', 'Explore the decision-making process without challenging the outcome directly. Ask: what would need to be true for this to be the right call? Then ask: what would tell you it was the wrong call? This surfaces the assumptions without creating defensiveness.', '["RC-680", "RC-684", "RC-720"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.463181+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('17', 'Mindset Layer — Belief Pattern', 'language_signal', 'What the founder believes is possible about themselves and the world. Covers confidence vs imposter feelings, fixed vs growth orientation, and identity beliefs. Around 78% of small business owners experience imposter syndrome. Fixed-mindset language — ''I will never be good at pitching'' — is a reliable diagnostic signal.', '["Identity-based limitations stated as facts: ''I am not a salesperson''", "Over-generalisation from single failures: ''we tried that — it never works''", "Imposter syndrome language: ''I feel like a fraud who will be found out''", "Fixed-mindset framing: ''I am just not the kind of person who can do X''", "33% chance success belief despite contrary data — irrational optimism as self-protection"]', '["I feel like a fraud", "I will never be good at pitching", "People like us do not build successful companies", "I am just not a natural leader", "I have always been bad at sales", "If I fail everyone will know I was never good enough", "I do not have what it takes"]', 'I am just not a sales person — it is not who I am', 'I have a limiting belief about my capability that I have never challenged — and the fear of failing at sales is protecting me from trying', 'Do not challenge the belief with logic — that creates defensiveness. Instead ask for evidence: ''Has there ever been a time when you persuaded someone of something important to you — even outside business?'' This starts building a new evidence base without confronting the belief directly.', '["RC-681", "RC-685", "RC-721"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.621655+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('18', 'Being Layer — Identity Crisis Pattern', 'language_signal', 'The founder''s core sense of self tied entirely to the business. Identity foreclosure — fusing entirely with the venture — creates existential risk. When the company falters, the founder feels they are losing themselves. Founders with broader self-concepts show consistently greater resilience under pressure.', '["Cannot describe who they are outside of their role as founder", "Business setbacks feel deeply personal — not operational problems but personal failures", "Phrases that tie personal worth to company outcomes", "Inability to consider pivoting because the original idea is who they are", "Fear that others see their company''s struggles as evidence of personal inadequacy"]', '["If this fails I do not know who I am", "This company is everything to me", "I have given this my whole life", "I cannot separate myself from this", "If it goes under I go under", "My family will see me as a failure", "I am nothing without this"]', 'If the company fails I do not know who I am anymore', 'I have fused my entire identity with this venture and the prospect of its failure feels like the prospect of my own disappearance', 'This is the most vulnerable layer. Acknowledge the depth of commitment before anything else. Then gently introduce a different frame: ''The person who built this company — the curiosity, the persistence, the care — those things do not live in the company. They live in you. Where else do they show up?''', '["RC-682", "RC-689", "RC-722"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.515344+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('19', 'Venture-Speak — Optimistic Reframing', 'language_signal', 'The startup world has its own language. Founders use specific phrases to sound confident, protect their image, or avoid difficult truths — sometimes without realising it. ClarityOS must learn to translate venture-speak into what it actually means so it can probe the reality beneath the performance.', '["Using industry phrases to describe metrics that sound stronger than they are", "Framing pre-revenue or pre-commitment situations as established revenue", "Describing founder sacrifice as company health", "Describing interest or conversations as committed pipeline", "Using positive anecdotes from biased sources as market validation"]', '["We are at a strong run rate", "We have committed revenue in the pipeline", "We are profitable and running lean", "Early user feedback has been very positive", "We are prioritising growth over monetisation", "We are in a temporary alignment phase", "I am deeply involved in quality control"]', 'We are at a strong run rate with committed revenue in the pipeline', 'Numbers are small and conversations have not converted yet — I am presenting the most optimistic interpretation of where we are', 'Do not call out the reframing directly — that creates shame and defensiveness. Instead probe with specific questions: ''When you say committed revenue — what does that look like in concrete terms? Signed contracts, paid deposits, or something else?'' The goal is specificity, not confrontation.', '["RC-683", "RC-691", "RC-723"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.67178+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('20', 'Going Quiet After Failure', 'stress_response', 'The most common first response to failure or serious setback is silence — not laziness or deception, but silence driven by shame, shock, and the inability to process what just happened. When a founder goes quiet after bad news, ClarityOS should recognise this as distress, not indifference.', '["Communication stopping or becoming very sparse after a significant setback", "Not updating investors, team, or advisors when they would normally do so", "Responding only to urgent operational matters — all non-essential communication paused", "Monosyllabic or very short responses to what would normally generate longer engagement", "Disappearing from communities, peer groups, or mentoring relationships temporarily"]', '["I have just been dealing with some things", "I will be back in touch soon", "Not much to update right now", "Everything is fine", "I needed some time to think", "I am just processing things"]', 'I have just been dealing with some things — I will be in touch', 'I am in shock and shame and I do not know how to face anyone while processing this', 'Reach in gently — do not demand a report. ''It has been quieter than usual and I wanted to check in — not about the business, just about you. How are you actually doing?'' Make the human connection before any business conversation.', '["RC-706", "RC-710", "RC-724"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.567672+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('21', 'Brave Face Performance', 'stress_response', 'After the initial shock of failure, founders shift into performing confidence. They tell their team everything is fine, tell investors they are learning from it. This is not dishonesty — it is a survival mechanism. Admitting the depth of the difficulty feels too dangerous when so many people depend on you.', '["Unusually upbeat presentation immediately after receiving clearly bad news", "Framing significant failures as minor learning moments in communications", "Performing enthusiasm for the team that is visibly effortful rather than natural", "Investor updates that contain only positive framing with no honest risk discussion", "Dismissing serious concerns raised by advisors or team with confident reassurance"]', '["This is all part of the journey", "Every setback is a setup for a comeback", "We are learning so much from this", "The team is energised and focused", "We have full confidence in the path", "This actually clarified a lot for us", "We are in a great place to come back stronger"]', 'This is actually clarifying — we are learning a lot and coming back stronger', 'I am scared and I cannot let anyone see that because I believe confidence is what keeps everyone else going', 'Create space for the real experience without demanding it. ''It sounds like you are finding the positive in a difficult moment — that is important. When you have a quiet moment away from everyone, what does it actually feel like?'' The private question gives permission for the private truth.', '["RC-663", "RC-692", "RC-725"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.722446+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('22', 'Avoidance Loop Pattern', 'stress_response', 'Each rejection triggers a small identity attack. After repeated rejections, founders start avoiding the situations that trigger rejection — they stop making sales calls, reaching out to investors, asking for customer feedback. Avoidance is presented as strategy but is almost always driven by accumulated emotional cost.', '["Sales activity declining without a stated strategic reason", "Investor outreach stopping after a series of rejections", "Customer feedback collection becoming less frequent or stopping", "Framing avoidance as strategic patience or timing", "Engaging only with warm inbound rather than initiating new conversations", "Busy work increasing as avoidance of the key high-stakes activities"]', '["Now is not the right time to fundraise", "We are being selective about which customers we approach", "We are letting the product speak for itself", "I am waiting for the right moment", "We do not want to come across as desperate", "Quality over quantity in our outreach", "The market will come to us"]', 'We are being strategic about our approach — waiting for the right moment', 'The repeated rejection has become emotionally costly enough that avoiding the situation feels safer than facing another no', 'Name what rejection actually feels like without accusing them of avoidance: ''Repeated rejection takes a real toll — it is exhausting in a way that does not show up on any spreadsheet. How has the pattern of not getting traction been affecting you personally?'' Then work from the emotional reality outward to the tactical question.', '["RC-662", "RC-677", "RC-726"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.845585+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('23', 'Societal Narrative — Family and Cultural Conditioning', 'language_signal', 'Before a founder even starts a business, they carry inherited narratives from family and society. These borrowed beliefs are not the founder''s own — they are conditioning from their environment. In Indian context these narratives include government jobs as safest, business is too risky, people like us do not build startups.', '["Expressing limits on ambition using family or community as justification", "Describing their background as a reason certain paths are not for them", "Guilt about family expectations when pursuing entrepreneurship", "Fear of what family will think if the startup fails — beyond personal shame", "Setting smaller goals than their capability suggests — holding back due to inherited ceiling"]', '["People from my family do not do things like this", "Where I come from this is not how business works", "My parents would never understand this approach", "If this fails I cannot face my family", "I was not raised with this kind of ambition", "People like us have to be more careful", "I cannot afford to fail the way someone else might"]', 'People from my background are not usually the ones building companies like this', 'I carry an inherited ceiling on what is possible for me and it is limiting my ambition in ways I have not fully examined', 'Surface the narrative without challenging its source. ''That belief sounds like it came from somewhere important to you. When did you first hear that people like you do not build companies like this?'' The goal is to help the founder see the belief as inherited — not inherent.', '["RC-678", "RC-683", "RC-727"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.77417+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('24', 'Stage 1 Ideation — Overthinking and Decision Paralysis', 'language_signal', 'At the Ideation stage, Being and Mindset layers dominate. Societal narratives and self-doubt are the primary blockers. The founder overthinks, second-guesses, stays up rehearsing scenarios, and delays the first action indefinitely. Both overconfidence and complete paralysis are present simultaneously.', '["Building more instead of showing — using development as avoidance of feedback", "Certainty that they already know what customers want without having asked", "Rehearsing every possible negative scenario before taking any action", "Waiting for conditions to be exactly right before sharing the idea", "Simultaneously over-confident about the idea and paralysed about the first step"]', '["I just need to build it a bit more before I show people", "I already know what customers want", "I am waiting for the right time to launch", "I need it to be perfect before anyone sees it", "I have thought through every possible scenario", "Once it is ready I will reach out to customers"]', 'I just need to build it a bit more before I show people', 'I am afraid of what real feedback will tell me so I am staying safe in the building phase where I control everything', 'Validate the care that perfectionism represents — it comes from wanting to do well. Then ask: ''What is the smallest version of this you could show someone tomorrow — not to launch, just to learn?'' Reduce the stakes of the first exposure to make it feel survivable.', '["RC-660", "RC-676", "RC-728"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.8247+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('25', 'Stage 3 MVP — Burnout Risk from Iteration Cycles', 'burnout_stage', 'At MVP stage, Body and Mind layers are under maximum strain. Anxiety about user reception, working extreme hours, and self-doubt about technical skills combine into the highest burnout risk of the early stages. The pressure of real users creating real feedback creates the first genuine psychological stress test.', '["Working hours extending further into nights and weekends", "High anxiety about what users will think before they have even seen the product", "Technical self-doubt increasing as the product becomes real", "Polishing instead of launching — perfectionism as protection from user judgment", "First signs of physical strain appearing — sleep disruption, missed meals"]', '["I just need it to be a bit more polished before I show anyone", "What if they hate it", "I am not sure the technical quality is there yet", "I have been working around the clock", "I just need one more week to get it right", "I do not know if I am technically good enough for this"]', 'I just need it to be a bit more polished before I show anyone', 'I am terrified of the first real user judgment because I know how much of myself I have put into this', 'Normalise the fear of first exposure — it is universal and makes sense. Then reframe what feedback means: ''What if the first user hating it gave you the exact information you needed to build something they would love? That feedback is worth more than six more months of polishing.''', '["RC-661", "RC-664", "RC-729"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.877467+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('26', 'Stage 5 Growth — Identity Fusion and Burnout Acceleration', 'burnout_stage', 'At the Growth stage, Intent and Being layers are under maximum strain. Burnout accelerates as work becomes entire identity. Any criticism of the business feels personal. The founder cannot separate their self-worth from the company''s performance metrics.', '["Deep personal investment in every business decision — cannot step back", "Investor feedback about the company felt as personal criticism", "Cannot take a day off without significant anxiety about what is happening without them", "Describing the company''s achievements as their own worth", "Defensive responses to strategic questions that are actually reasonable"]', '["I am deeply involved in every part of the business", "When the company does well I feel like I am worth something", "If an investor criticises the product they are criticising me", "I cannot step back — everything depends on me being involved", "I have given everything to this", "The company IS me"]', 'I am deeply involved in every part of the business — I have to be', 'I have fused my identity completely with this company and I am burning out because the company''s problems feel like my personal failures', 'Acknowledge the commitment and the cost of it simultaneously. ''It is clear how much you have put into this — and that level of investment means the company''s struggles hit you in a very personal way. When did you last have a day that was completely yours?'' Create a small opening for self-identity outside the business.', '["RC-662", "RC-665", "RC-730"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:18.629885+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
insert into "behaviour_patterns" ("pattern_id", "pattern_name", "pattern_type", "description", "observable_signals", "language_cues", "what_they_say", "what_they_mean", "empathy_response", "linked_root_cause_ids", "created_at", "updated_at", "embedding_model", "embedding_version", "embedding_dimension") values ('27', 'Stage 7 Maturity — Identity Crisis at the Top', 'burnout_stage', 'At the Maturity stage, the Being layer is in crisis. Loneliness at the top, loss of mission adrenaline, and the beginnings of identity fracture outside the company create a specific psychological pattern that is rarely discussed but very common. The founder who built something significant now must navigate who they are when the building phase is over.', '["Expressing doubt about whether this is still what they wanted to build", "Frustration at loss of hands-on work — missing the early building phase", "Loneliness despite being surrounded by a large team", "Questions about purpose and meaning that are new for this founder", "Comparing current role unfavourably to who they were at Stage 1 or 2"]', '["I wonder if this is still what I actually wanted to build", "I miss when it was just us building things", "I do not know who I am if I hand this over", "I feel lonely in a way I did not expect", "The role has changed so much — I am not sure it suits me anymore", "I built this but I am not sure I am the right person to run it"]', 'I wonder if this is still what I actually wanted to build', 'I am experiencing a loss of the identity and purpose that the building phase gave me — and I do not know what comes next', 'This is one of the loneliest moments in a founder''s journey and it is rarely acknowledged. ''What you are describing is actually very common at this stage — the thing you built to find meaning has grown into something that no longer gives you the same kind of meaning. What parts of the early journey do you most miss?'' Start rebuilding a sense of purpose from what they valued then.', '["RC-663", "RC-666", "RC-731"]', '2026-07-10 17:12:53.417223+00', '2026-08-03 03:27:19.936466+00', 'text-embedding-3-small', 'v1', '1536') on conflict do nothing;
